sys_variable_value.value:
/**
 * Captures approver / decision / comments / timestamp from the platform
 * approval (sysapproval_approver), appends the audit entry to
 * ai_recommendation + closure_notes, and completes a bfd_case_task of type
 * 'approval' carrying the outcome.
 */
(function execute(inputs, outputs) {
    var result = new bfd_FlowSupport().logApprovalDecision(inputs.caseSysId, inputs.decision);
    outputs.approver = result.approverName || '';
    outputs.comments = result.comments || '';
    outputs.decidedAt = result.decidedAt || '';
})(inputs, outputs);

